/* ---- reveal ---- */
var io=('IntersectionObserver' in W)?new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:.12,rootMargin:'0px 0px -6% 0px'}):null;
function watch(){D.querySelectorAll('.rv:not(.in)').forEach(function(el){io?io.observe(el):el.classList.add('in')})}

/* ---- saatler / açık mı ---- */
var HOURS=CFG.hours||[12,24];
function nowIst(){var d=new Date();try{var p=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Istanbul',hour:'numeric',minute:'numeric',weekday:'short',hour12:false}).formatToParts(d);var o={};p.forEach(function(x){o[x.type]=x.value});return {h:+o.hour%24,m:+o.minute,wd:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(o.weekday)}}catch(e){return {h:d.getHours(),m:d.getMinutes(),wd:d.getDay()}}}
function sunsetIst(){var d=new Date(),n=Math.floor((d-new Date(d.getFullYear(),0,0))/864e5),lat=41.08,lng=29.04;
  var g=(2*Math.PI/365)*(n-1),eq=229.18*(0.000075+0.001868*Math.cos(g)-0.032077*Math.sin(g)-0.014615*Math.cos(2*g)-0.040849*Math.sin(2*g));
  var dec=0.006918-0.399912*Math.cos(g)+0.070257*Math.sin(g)-0.006758*Math.cos(2*g)+0.000907*Math.sin(2*g)-0.002697*Math.cos(3*g)+0.00148*Math.sin(3*g);
  var la=lat*Math.PI/180,ha=Math.acos(Math.cos(90.833*Math.PI/180)/(Math.cos(la)*Math.cos(dec))-Math.tan(la)*Math.tan(dec))*180/Math.PI;
  var mins=720-4*(lng-ha)-eq+180; var h=Math.floor(mins/60),m=Math.round(mins%60);return (h<10?'0':'')+h+':'+(m<10?'0':'')+m}
W.novaSunset=sunsetIst;
function openBadge(){var b=D.querySelector('.open-badge');if(!b)return;var n=nowIst(),h=n.h+n.m/60,open=h>=HOURS[0]&&h<HOURS[1];
  b.classList.toggle('closed',!open);b.querySelector('b').textContent=t(open?'home.open':'home.closed');
  b.querySelector('small').textContent=open?t('home.until',{t:'00:00'}):t('home.opens',{t:'12:00'});
  var s=D.querySelector('.sunset');if(s)s.textContent=t('home.sunset',{t:sunsetIst()})}
D.addEventListener('nova:lang',openBadge);

/* ---- intro ---- */
(function(){
  var intro=D.getElementById('intro');if(!intro)return;
  var force=/[?&]intro=1/.test(location.search),ref=D.referrer,inSite=ref&&ref.indexOf(location.host)>=0,
      nav=(performance.getEntriesByType&&performance.getEntriesByType('navigation')[0])||{},reload=nav.type==='reload';
  var seen=false;try{seen=sessionStorage.getItem('nova-intro')==='1'}catch(e){}
  if(!force&&(seen||location.hash||(inSite&&!reload))){D.documentElement.classList.add('nointro');intro.remove();return}
  try{sessionStorage.setItem('nova-intro','1')}catch(e){}
  D.body.style.overflow='hidden';
  var done=false,v=D.createElement('video'),bar=intro.querySelector('.bar'),cap=intro.querySelector('.cap'),ok=false,mob=innerWidth<innerHeight;
  var CAPS=[[1.2,'intro.c1'],[3.4,'intro.c2'],[6.4,'intro.c3']],ci=-1;
  function finish(){if(done)return;done=true;intro.classList.add('out');D.body.style.overflow='';setTimeout(function(){intro.remove()},1000)}
  function simple(){if(done)return;intro.classList.add('simple','logo-on');setTimeout(finish,2600)}
  var base=mob?'assets/intro-m':'assets/intro';
  v.muted=true;v.defaultMuted=true;v.playsInline=true;v.autoplay=true;v.preload='auto';v.setAttribute('muted','');v.setAttribute('playsinline','');v.setAttribute('webkit-playsinline','');v.setAttribute('aria-hidden','true');
  v.innerHTML='<source src="'+base+'.webm?v='+CFG.v+'" type="video/webm"><source src="'+base+'.mp4?v='+CFG.v+'" type="video/mp4">';
  intro.insertBefore(v,intro.firstChild);
  function tick(){if(done)return;var T=v.currentTime,L=v.duration||10.15;bar.style.width=(T/L*100)+'%';
    var n=-1;for(var i=0;i<CAPS.length;i++)if(T>=CAPS[i][0])n=i;
    if(n!==ci){ci=n;cap.classList.remove('on');if(n>=0)(function(n){setTimeout(function(){cap.textContent=t(CAPS[n][1]);cap.classList.add('on')},160)})(n)}
    if(T>7.9)intro.classList.add('logo-on');
    if(T>L-.9)cap.classList.remove('on');
    if(v.ended||T>=L-.05){finish();return}requestAnimationFrame(tick)}
  v.addEventListener('playing',function(){if(ok)return;ok=true;requestAnimationFrame(tick)});
  v.addEventListener('ended',finish);
  v.addEventListener('error',function(){if(!ok)simple()},true);
  var p;try{p=v.play()}catch(e){}if(p&&p.catch)p.catch(function(){setTimeout(function(){if(!ok)simple()},300)});
  setTimeout(function(){if(!ok)simple()},4000);
  intro.querySelector('.skip').addEventListener('click',finish);
  D.addEventListener('keydown',function(e){if(e.key==='Escape')finish()});
})();

